import {ALL_HISTORY_EVENTS as CATALOG} from './history-catalog.js';
import {lifeStage} from './avatar.js';
import {policyFor,policyWeight,POLICY_EVENTS} from './policy-data.js';
import {MARKET_ASSETS,MARKET_BY_ID,STOCK_IDS,MARKET_EVENTS,ALLOCATIONS} from './market-data.js';
import {marketValue,reportFor,eventsFor} from './market.js';
export function marketChart(s,id,period=36){const h=s.market.history.slice(-period),values=h.map(x=>x.prices[id]),min=Math.min(...values),max=Math.max(...values),spread=max-min||1;const p=h.map((x,i)=>`${14+(h.length>1?i/(h.length-1):0)*472},${139-(x.prices[id]-min)/spread*115}`).join(' ');return `<svg class="market-chart" viewBox="0 0 500 160" role="img" aria-label="${MARKET_BY_ID[id].name} 모형 가격, 지난 ${h.length}개 월 기록"><path d="M14 24H486 M14 82H486 M14 139H486" fill="none" stroke="#dce6ed" stroke-dasharray="4 4"/><polyline points="${p}" fill="none" stroke="#218aff" stroke-width="3" stroke-linecap="round"/><circle cx="${h.length>1?486:14}" cy="${139-(values.at(-1)-min)/spread*115}" r="5" fill="#218aff"/></svg>`;}
export function renderImpact(s,{escape:e,won,date}){const reports=(s.market?.reports||[]).filter(r=>r.month===s.month);if(!reports.length)return '';return `<section class="market-impact"><div class="section-heading"><div><span class="eyebrow">EVENT → MY PORTFOLIO</span><h3>이번 달 사건이 내 자금에 남긴 변화.</h3></div><span class="mini-label">${date(s.month)} / 모형 효과</span></div>${reports.map(r=>{const event=CATALOG.find(x=>x.id===r.id)||eventsFor(r.month,s.market?.model,s.market?.historyEdition).find(x=>x.id===r.id);return `<article><div class="impact-head"><div><span class="mini-label">${event.future?'가상 미래 사건':'출처 있는 역사 사건'}</span><h4>${e(event.title)}</h4></div><strong class="${r.delta<0?'negative':'positive'}">${won(r.delta)}</strong></div><div class="impact-tags">${MARKET_ASSETS.filter(a=>Math.abs(r.changes[a.id])>=1).map(a=>`<span>${a.name} <b class="${r.changes[a.id]<0?'negative':'positive'}">${won(r.changes[a.id])}</b></span>`).join('')||(event.educationOnly?'<span>사실과 조건을 배우는 카드입니다. 인위적인 가격 충격·개별 피해액을 적용하지 않아 사건 효과는 0원입니다.</span>':event.policy?'<span>취임·정책 발표 자체로 현금을 일괄 변경하지 않습니다. 정책 방향은 다음 달부터 모형의 산업 반응과 금융 환경에 반영됩니다.</span>':'<span>사건 당시 영향을 받는 자산을 보유하지 않아 직접 평가손익이 없어요.</span>')}</div>${event.url?`<a class="source" href="${e(event.url)}" target="_blank" rel="noopener noreferrer">${e(event.source)} · 날짜·사실의 출처 ↗</a>`:''}</article>`;}).join('')}<p class="note">사건 직전 보유 수량으로 계산한 가격 효과입니다. 월 기본 변동·이자·생활비·주택은 별도예요. 이미 반영된 변화이며 지금 매매해 과거 손익을 되돌릴 수 없습니다. 원화 현금 자체는 주가와 함께 떨어지지 않지만 물가에 따라 구매력이 달라집니다.</p></section>`;}

export function renderPolicyContext(s,{escape:e,date}){const p=policyFor(s.month);if(!p)return `<section class="policy-context"><span class="mini-label">GOVERNMENT & POLICY</span><h3>정부·정책 변화도 시장의 배경이 됩니다.</h3><p>대통령 취임과 정책 발표를 해당 시기에 만나고, 발표된 산업·사회 방향을 게임의 경제 환경에 연결합니다.</p></section>`;const event=POLICY_EVENTS.find(x=>x.id===p.eventId),w=policyWeight(p,s.month);return `<section class="policy-context"><div class="section-heading"><div><span class="eyebrow">GOVERNMENT → POLICY → MARKET</span><h3>${e(p.name)}</h3></div><span class="mini-label">${date(p.month)} 발표 기준의 정책 모형</span></div><div class="policy-topics">${p.topics.map(t=>`<span>${e(t)}</span>`).join('')}</div><div class="policy-paths"><article><b>산업·사회 방향</b><p>발표 주제에 따라 가상 산업의 월 반응 계수를 바꿉니다. 정책 수혜가 항상 수익으로 이어지는 것은 아닙니다.</p></article><article><b>대외 환경과 환율</b><p>원/달러 모형의 외부 변동 민감도 ${((1+(p.fxSensitivity-1)*w)*100).toFixed(0)}%. 대통령 이름으로 환율 방향을 고정하지 않습니다.</p></article><article><b>내수·금융 환경</b><p>모형 물가·예금금리의 완만한 복귀 기준에 정책 계수를 연결합니다. 한국은행 실제 결정이나 실제 인과 효과를 재현한 값은 아닙니다.</p></article></div><a class="source" href="${e(event.url)}" target="_blank" rel="noopener noreferrer">${e(event.source)} · 취임·발표 사실 ↗</a>${event.policyUrl?`<a class="source" href="${e(event.policyUrl)}" target="_blank" rel="noopener noreferrer">발표된 국정방향 출처 ↗</a>`:''}<p class="note">정책 방향만 공식 자료로 확인했습니다. 수치 계수는 검증된 경제 추정치가 아닌 게임 가정입니다. 최대 60개월 적용하고 다음 방향 발표로 교체합니다. 현재 정부·재임 기간의 완전한 표시가 아닙니다.</p></section>`;}

export function renderMarket(s,{escape:e,won,date,selected='chip',period=36}){if(!s.market)return `<section class="market-enable"><span class="eyebrow">HISTORY MEETS MY MONEY</span><h2>현금 다음의 선택.</h2><p>기존 삶에 경제 시장을 연결합니다.<br>현금·예금은 그대로 두고 기존 분산 주식만 같은 평가액의 IF 분산시장 수량으로 옮깁니다.</p><button class="btn" data-market-enable="true" ${s.ended?'disabled':''}>이 삶의 경제 시장 열기 →</button><p class="game-assumption">앞으로의 환율·주가·금리·물가·주택 수익률은 새 모형을 적용합니다. 과거 손익을 다시 계산하지 않아요. 모든 시세·수익률은 가정이며 실제 역사 가격 자료는 아직 연결하지 않았습니다.</p></section>`;
 const locked=s.ended||(s.startMode==='birth'&&lifeStage(s).years<19);const m=s.market,asset=MARKET_BY_ID[STOCK_IDS.includes(selected)?selected:'chip'],history=m.history,prev=history.at(-2)?.prices[asset.id]||m.prices[asset.id],change=(m.prices[asset.id]/prev-1)*100,total=marketValue(s)+s.cash+s.deposit,h=m.holdings[asset.id]||{units:0,basis:0},value=Math.round(h.units*m.prices[asset.id]);const portions=[{name:'원화 현금',value:s.cash,color:'#c8d5e1'},{name:'원화 예금',value:s.deposit,color:'#9acbfa'},{name:'달러',value:Math.round((m.holdings.usd?.units||0)*m.prices.usd),color:'#58a4df'},{name:'금',value:Math.round((m.holdings.gold?.units||0)*m.prices.gold),color:'#dfb758'},{name:'테마 주식',value:STOCK_IDS.reduce((v,id)=>v+Math.round((m.holdings[id]?.units||0)*m.prices[id]),0),color:'#3263bd'}];
 return `<section class="market-heading"><div><span class="eyebrow">IF ECONOMY / MY CAPITAL</span><h2>같은 사건,<br>다르게 움직이는 나의 자금.</h2><p>자산을 바꾸고 다음 달을 만나요.<br>한 사건이 모든 자산에 같은 호재·악재가 되지는 않습니다.</p></div><div class="market-time"><span class="mini-label">${date(s.month)} / ${s.month>'2026-10'?'가상 미래':'월 단위 역사 모형'}</span><button class="btn" data-advance="1" ${s.pending||s.ended?'disabled':''}>한 달 진행 →</button><button class="btn secondary small" data-advance="12" ${s.pending||s.ended?'disabled':''}>다음 사건까지</button></div></section><div class="market-life-mode"><div><span class="mini-label">GAME FOCUS</span><b>${m.lifeEvents===false?'큰 시장 사건에서 멈추는 경제 중심 플레이':'시장과 인생의 이야기를 함께 플레이'}</b><small>진행 중인 선택은 먼저 마무리해요. 최대 12개월 진행 중 사건이 생기면 멈춥니다.</small></div><div role="group" aria-label="경제 플레이 방식"><button data-market-life="off" class="${m.lifeEvents===false?'active':''}" aria-pressed="${m.lifeEvents===false}">경제 사건 중심</button><button data-market-life="on" class="${m.lifeEvents!==false?'active':''}" aria-pressed="${m.lifeEvents!==false}">삶과 함께</button></div></div><div class="capital-receipt"><span>${s.startMode==='birth'?'가족의 가상 시작 자산':'당첨 시작 설정 수령액'} <b>${won(s.initial)}</b></span><span>초기 자산 배분 수수료 <b>${won(m.initialFees||0)}</b></span></div><div class="market-assumption">환율·주가·금 가격·예금금리·수익률은 실제 시세가 아닌 게임 모형입니다. 역사 사건의 사실·날짜만 출처를 확인했습니다. 하루 단위 거래와 실제 투자 결과를 재현하지 않습니다.</div>${s.pending?`<div class="market-pending"><div><span class="mini-label">진행 전에 확인할 이야기</span><b>${e(s.pending.title)}</b>${s.pending.origin?`<span class="story-origin">이 이야기가 열린 이유 · ${e(s.pending.origin)}</span>`:''}<small>${s.pending.economicId?'그달 시장 변동은 이미 반영됐어요. 매매한 뒤 사건을 확인할 수 있습니다.':'선택을 마치면 시간을 진행할 수 있어요.'}</small></div><button class="btn secondary small" data-tab="life">사건과 선택 보기 →</button></div>`:''}${renderPolicyContext(s,{escape:e,date})}<div class="market-metrics"><article><small>금융 자금 합계</small><strong>${won(total)}</strong><span>현금·예금·달러·금·주식</span></article><article><small>원/달러 모형 환율</small><strong>${won(m.prices.usd)}</strong><span>1달러 기준 · 실제 환율 아님</span></article><article><small>금 모형 원화 가격</small><strong>${won(m.prices.gold)}</strong><span>1g 기준 · 환율 함께 반영</span></article><article><small>원화 예금 모형 연 금리</small><strong>${(m.deposit*100).toFixed(2)}%</strong><span>변동 금리 · 이자는 매월 현금 지급</span></article></div><section class="portfolio-mix"><div class="section-heading"><h3>내 자금의 구성</h3><span class="mini-label">주거·차량·소장품은 별도</span></div><div class="mix-bar" aria-label="금융 자산 구성">${portions.map(p=>`<span style="width:${total>0?p.value/total*100:0}%;background:${p.color}"></span>`).join('')}</div><div class="mix-labels">${portions.map(p=>`<span><i style="background:${p.color}"></i>${p.name} <b>${total>0?(p.value/total*100).toFixed(1):0}%</b></span>`).join('')}</div><div class="deposit-controls"><button class="btn secondary small" data-action="deposit" ${locked||s.cash<10000000?'disabled':''}>예금에 1,000만 원 넣기</button><button class="btn secondary small" data-action="withdraw" ${locked||s.deposit<=0?'disabled':''}>예금에서 최대 1,000만 원 인출</button></div></section><div class="exchange-grid">${['usd','gold'].map(id=>{const a=MARKET_BY_ID[id],p=m.holdings[id]||{units:0,basis:0},v=Math.round(p.units*m.prices[id]);return `<article class="exchange-card"><span class="mini-label">${a.symbol}</span><h3>${a.name}으로 바꾸기</h3><p>${a.description}</p><div class="exchange-quote"><span>보유 ${p.units.toLocaleString('ko-KR',{maximumFractionDigits:id==='usd'?2:3})}${a.unit}</span><b>${won(v)}</b></div><small>매매 수수료 ${(a.fee*100).toFixed(1)}% · 세금 미반영</small><div class="exchange-actions"><button class="btn small" data-trade-open="${id}:buy" ${locked?'disabled':''}>매수·환전</button><button class="btn secondary small" data-trade-open="${id}:sell" ${locked||p.units<=0?'disabled':''}>팔고 현금으로</button></div></article>`;}).join('')}</div><section class="stock-terminal"><div class="section-heading"><div><span class="eyebrow">ONE STOCK FOR EACH THEME</span><h3>테마별 가상 주식 시장</h3></div><span class="mini-label">실제 기업·지수 아님</span></div><div class="stock-layout"><nav class="stock-list" aria-label="테마 주식 선택">${STOCK_IDS.map(id=>{const a=MARKET_BY_ID[id],past=history.at(-2)?.prices[id]||m.prices[id],c=(m.prices[id]/past-1)*100;return `<button data-market-stock="${id}" class="${asset.id===id?'active':''}" aria-pressed="${asset.id===id}"><span><b>${a.name}</b><small>${a.theme}</small></span><span><b>${won(m.prices[id])}</b><small class="${c<0?'negative':'positive'}">${history.length>1?(c>=0?'+':'')+c.toFixed(2)+'%':'첫 기록'}</small></span></button>`;}).join('')}</nav><article class="stock-detail"><div class="stock-title"><div><span class="mini-label">${asset.symbol}</span><h3>${asset.name}</h3><p>${asset.description}</p></div><div><strong>${won(m.prices[asset.id])}</strong><span class="${change<0?'negative':'positive'}">${history.length>1?'전월 대비 '+(change>=0?'+':'')+change.toFixed(2)+'%':'첫 관측 · 전월 기록 없음'}</span></div></div><div class="chart-periods" role="group" aria-label="가격 기록 기간">${[12,36,1500].map(n=>`<button data-market-period="${n}" class="${n===period?'active':''}" aria-pressed="${n===period}">${n===1500?'플레이 전체':n+'개월'}</button>`).join('')}</div>${marketChart(s,asset.id,period)}<p class="note">${date(history.slice(-period)[0].month)} ~ ${date(s.month)} · 플레이한 월의 모형 가격만 표시</p><div class="stock-position"><div><small>보유 수량</small><b>${h.units.toLocaleString('ko-KR',{maximumFractionDigits:4})}주</b></div><div><small>평가액</small><b>${won(value)}</b></div><div><small>취득원가·수수료 포함</small><b>${won(h.basis)}</b></div><div><small>평가손익</small><b class="${value-h.basis<0?'negative':'positive'}">${won(value-h.basis)}</b></div></div><div class="stock-trade-buttons"><button class="btn" data-trade-open="${asset.id}:buy" ${locked?'disabled':''}>이 테마 매수</button><button class="btn secondary" data-trade-open="${asset.id}:sell" ${locked||h.units<=0?'disabled':''}>보유 주식 매도</button></div><p class="note">주식 매매 수수료 0.2%입니다. 공매도·레버리지·배당·세금은 미반영입니다. 처음 매수한 뒤에도 가격이 계속 오르는 것으로 가정하지 않습니다.</p></article></div></section>${renderImpact(s,{escape:e,won,date})}<section class="market-holdings"><div class="section-heading"><h3>보유 자산과 매매 기록</h3><button class="text-button" data-tab="journal">전체 장부 ↗</button></div><div class="holdings-grid">${MARKET_ASSETS.filter(a=>(m.holdings[a.id]?.units||0)>0).map(a=>{const h=m.holdings[a.id],v=Math.round(h.units*m.prices[a.id]);return `<article><span class="mini-label">${a.theme}</span><h4>${a.name}</h4><b>${won(v)}</b><small>${h.units.toLocaleString('ko-KR',{maximumFractionDigits:4})}${a.unit} · 평가손익 ${won(v-h.basis)}</small><button class="text-button" data-trade-all="${a.id}" ${locked?'disabled':''}>전량 매도 확인 →</button></article>`;}).join('')||'<p>아직 보유한 시장 자산이 없어요.</p>'}</div><div class="recent-trades">${m.trades.slice(-5).reverse().map(t=>`<div><time>${date(t.month)}</time><span>${MARKET_BY_ID[t.id].name} ${t.side==='buy'?'매수':'매도'}</span><b>${won(t.gross)}</b><small>수수료 ${won(t.fee)}${t.side==='sell'?' · 실현손익 '+won(t.realized):''}</small></div>`).join('')}</div></section>`;}
